      image: 'illo-m03-senses.jpg',
      practitioners: ['Artem Talalay (World Class Russia Winner)', 'Dave Arnold (Liquid Intelligence)', 'Hiroyasu Kayama (Bar Benfiddich)', 'Jiro Ono (Sukiyabashi Jiro)'],
